올려주신 MCP자료 덕분에 드뎌 볼게이노 셋팅 완료햇어요.
모두들 이렇게 좋은정보를 공유해주셔서 뭐라 감사드려야할지. . .진심으로 감사드립니다

& { if (-not (Get-Command code -ErrorAction SilentlyContinue) -and -not (Test-Path "$env:LOCALAPPDATA\Programs\Microsoft VS Code\Code.exe")) { Write-Host '[1/4] VS Code 설치 중...' -ForegroundColor Cyan; winget install --id Microsoft.VisualStudioCode -e --silent --accept-source-agreements --accept-package-agreements } else { Write-Host '[1/4] VS Code 준비 완료!' -ForegroundColor Green }; $bin = "$env:USERPROFILE\.local\bin"; if (-not (Test-Path "$bin\claude.exe") -and -not (Get-Command claude -ErrorAction SilentlyContinue)) { Write-Host '[2/4] Claude Code 설치 중...' -ForegroundColor Cyan; irm https://claude.ai/install.ps1 | iex } else { Write-Host '[2/4] Claude Code 이미 설치됨 (건너뜀)!' -ForegroundColor Green }; $curPath = [Environment]::GetEnvironmentVariable('Path', 'User'); if ($curPath -notlike "*$bin*") { [Environment]::SetEnvironmentVariable('Path', "$curPath;$bin", 'User'); $env:Path += ";$bin" }; Write-Host '[3/4] Volcano MCP 연결 확인 중...' -ForegroundColor Cyan; & "$bin\claude.exe" mcp add --transport http volcano --scope user https://volcano-mcp.groove1027.workers.dev 2>$null; Write-Host '`n[4/4] 작업할 폴더를 선택해주세요 (화면에 뜬 창 확인)...' -ForegroundColor Yellow; Add-Type -AssemblyName System.Windows.Forms; $dialog = New-Object System.Windows.Forms.FolderBrowserDialog; $dialog.Description = 'Claude Code를 실행할 프로젝트 폴더를 선택하세요'; $dialog.ShowNewFolderButton = $true; $topForm = New-Object System.Windows.Forms.Form; $topForm.TopMost = $true; $targetFolder = $env:USERPROFILE; if ($dialog.ShowDialog($topForm) -eq [System.Windows.Forms.DialogResult]::OK) { $targetFolder = $dialog.SelectedPath }; $topForm.Dispose(); $vscodeDir = Join-Path $targetFolder '.vscode'; if (-not (Test-Path $vscodeDir)) { New-Item -ItemType Directory -Path $vscodeDir -Force | Out-Null }; $taskJson = @'
{
  "version": "2.0.0",
  "tasks": [
    {
      "label": "Auto Claude Code",
      "type": "shell",
      "command": "claude --dangerously-skip-permissions",
      "runOptions": { "runOn": "folderOpen" },
      "presentation": { "reveal": "always", "panel": "new", "focus": true }
    }
  ]
}
'@; Set-Content -Path (Join-Path $vscodeDir 'tasks.json') -Value $taskJson -Encoding UTF8; $codePath = "$env:LOCALAPPDATA\Programs\Microsoft VS Code\Code.exe"; if (-not (Test-Path $codePath)) { $codePath = 'C:\Program Files\Microsoft VS Code\Code.exe' }; if (-not (Test-Path $codePath)) { $codePath = 'code' }; Write-Host "`n🎉 선택한 폴더로 VS Code를 열고 Claude Code를 자동 시작합니다!" -ForegroundColor Green; Start-Process $codePath -ArgumentList "`"$targetFolder`"" }
